exercise.solution:
class Cart {
  private items: Map<string, number> = new Map();

  add(sku: string, quantity: number): void {
    if (quantity <= 0) {
      throw new Error("Quantity must be positive");
    }

    this.items.set(sku, (this.items.get(sku) ?? 0) + quantity);
  }

  remove(sku: string): void {
    this.items.delete(sku);
  }

  itemCount(): number {
    let count = 0;

    for (const quantity of this.items.values()) {
      count += quantity;
    }

    return count;
  }

  total(prices: Record<string, number>): number {
    let sum = 0;

    for (const [sku, quantity] of this.items) {
      const price = prices[sku];

      if (price === undefined) {
        throw new Error(`Unknown product: ${sku}`);
      }

      sum += price * quantity;
    }

    return Math.round(sum * 100) / 100;
  }
}

