cart.add("BOOK-1", 2);
cart.add("BOOK-1", 3);

if (cart.itemCount() !== 5) {
  throw new Error(`Expected 5 items, got ${cart.itemCount()}`);
}

return true;

const cart = new Cart();
cart.add("BOOK-1", 2);
cart.add("PEN-1", 4);
cart.remove("BOOK-1");

if (cart.itemCount() !== 4) {
  throw new Error(`Expected 4 items, got ${cart.itemCount()}`);
}

return true;

const cart = new Cart();

let failed = false;
try {
  cart.add("BOOK-1", 0);
} catch (error) {
  failed = error instanceof Error && error.message === "Quantity must be positive";
}

if (!failed) {
  throw new Error("Expected non-positive quantity to be rejected");
}

return true;

const cart = new Cart();
cart.add("BOOK-1", 2);
cart.add("PEN-1", 3);

const total = cart.total({ "BOOK-1": 12.345, "PEN-1": 1.1 });
const rounded = Math.round(total * 100) / 100;

if (Math.abs(rounded - 27.99) >= 0.001) {
  throw new Error(`Expected 27.99, got ${total}`);
}

return true;

const cart = new Cart();
cart.add("BOOK-1", 2);

let failed = false;
try {
  cart.total({});
} catch (error) {
  failed = error instanceof Error && error.message === "Unknown product: BOOK-1";
}

if (!failed) {
  throw new Error("Expected unknown product to be rejected");
